{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a materially higher cap, taking account of the AUD 24m price and diligence findings."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek a lower de minimis and a tipping basket (recovery from the first dollar once crossed), rather than recovering only the excess."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer period and ensure a timely, sufficiently detailed notice preserves a claim through resolution."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Give title, ownership, capacity and authority warranties a separate, substantially higher cap (ideally the purchase price) and longer limitation period consistent with applicable law."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve out title/fundamental warranties, tax claims, specific indemnities, fraud, wilful misconduct and deliberate concealment, and agreed price adjustments."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Delete blanket data-room/public-register disclosure and the broad knowledge exclusion."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit any knowledge qualifier to actual knowledge of named Buyer personnel after reasonable enquiry, and exclude constructive or imputed knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make valid, unconditional consent and satisfaction of its conditions a condition precedent to Completion, with evidence delivered before Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment, lender payout and discharge/release of all security at or before Completion, supported by lender-controlled payout and release documentation."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "They should reduce the amount paid to the Seller or be funded/escrowed by it, not be left as an unpriced post-Completion company cost."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Add a specific indemnity covering loss of rights, infringement, remediation and related costs if the transfer is not secured."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Obtain a specific, uncapped (or separately capped at an appropriate level) indemnity for the incident, including investigation, notification, response and regulatory costs."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "reflect accrued or unavoidable pre-Completion commitments in the completion accounts or a specific adjustment if material."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Restrict the general cap, thresholds and warranty claim deadline to ordinary business warranties."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require evidence of legal and beneficial ownership, fully paid shares, absence of encumbrances/options, and transfer documents at Completion."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Negotiate tailored tax and IP warranties and appropriate limitation periods/caps."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

